program.compute:
options = read('/input/options')
ids = [x['id'] for x in options]
result = []
for k in range(1, goal['max_count'] + 1):
    for choice in combinations(ids, k):
        if valid(list(choice)):
            result = list(choice)
            break
    if result:
        break

program.effects:
if exists('/output/selection'):
    current = read('/output/selection')
    if not valid(current):
        status('report')
else:
    if not result or not valid(result):
        status('report')
    else:
        write('/output/selection', result)
state = status('report')
receipt_state = receipt('report')
if receipt_state == 'unattempted' and state == 'not_sent':
    send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')

